// ============================================================================
// I2C_Host_apb: APB4 register wrapper around I2C_Host_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/I2C_Host.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/I2C_Host.md
// ============================================================================
module I2C_Host_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  output logic scl,
  inout tri sda
);
  localparam logic [31:0] ID_VALUE = 32'h5C510100;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [9:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd10) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & ~|hit;

  // ---------------- core ----------------
  logic [15:0]   c_prescale;
  logic          c_cmd_valid;
  logic          c_cmd_sta;
  logic          c_cmd_wr;
  logic          c_cmd_rd;
  logic          c_cmd_sto;
  logic          c_cmd_nack;
  logic [7:0]    c_tx_data;
  logic [7:0]    c_rx_data;
  logic          c_rx_ack;
  logic          c_busy;
  logic          c_bus_held;
  logic          c_done;
  I2C_Host_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .scl(scl),
    .sda(sda),
    .prescale(c_prescale),
    .cmd_valid(c_cmd_valid),
    .cmd_sta(c_cmd_sta),
    .cmd_wr(c_cmd_wr),
    .cmd_rd(c_cmd_rd),
    .cmd_sto(c_cmd_sto),
    .cmd_nack(c_cmd_nack),
    .tx_data(c_tx_data),
    .rx_data(c_rx_data),
    .rx_ack(c_rx_ack),
    .busy(c_busy),
    .bus_held(c_bus_held),
    .done(c_done)
  );

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [15:0] r_PRESCALE;   // 12'h014 PRESCALE
  logic [7:0] r_TX_DATA;   // 12'h018 TX_DATA
  logic [5:0] p_CMD;   // 12'h01C CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_PRESCALE <= 16'h63;
      r_TX_DATA <= 8'h0;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[5]) r_PRESCALE <= (r_PRESCALE & ~wmask[15:0]) | (PWDATA[15:0] & wmask[15:0]);
      if (wr && hit[6]) r_TX_DATA <= (r_TX_DATA & ~wmask[7:0]) | (PWDATA[7:0] & wmask[7:0]);
      p_CMD <= (wr && hit[7]) ? PWDATA[5:0] & wmask[5:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_prescale = r_PRESCALE[15:0];
  assign c_tx_data = r_TX_DATA[7:0];
  assign c_cmd_valid = p_CMD[0:0];
  assign c_cmd_sta = p_CMD[1:1];
  assign c_cmd_wr = p_CMD[2:2];
  assign c_cmd_rd = p_CMD[3:3];
  assign c_cmd_sto = p_CMD[4:4];
  assign c_cmd_nack = p_CMD[5:5];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd5: apb_rdata = 32'(r_PRESCALE);
      10'd6: apb_rdata = 32'(r_TX_DATA);
      10'd8: apb_rdata = 32'({c_rx_ack, c_rx_data});
      10'd9: apb_rdata = 32'({c_bus_held, c_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
